use vstd::prelude::*;

verus! {

fn append_array(a: &[i32], b: &[i32]) -> (c: Vec<i32>)
    ensures
        c@.len() == a@.len() + b@.len(),
        // First part matches `a`
        forall|i: int| 0 <= i < a@.len() ==> c@[i] == a@[i],
        // Second part matches `b`, shifted by len(a)
        forall|j: int| 0 <= j < b@.len() ==> c@[a@.len() + j] == b@[j],
{
    let mut c: Vec<i32> = Vec::with_capacity(a.len() + b.len());

    let mut i: usize = 0;
    while i < a.len()
        invariant
            c@.len() == i as nat,
            i <= a.len(),
            // everything copied so far equals a[0..i]
            forall|k: int| 0 <= k < i as int ==> c@[k] == a@[k],
        decreases a.len() - i,
    {
        c.push(a[i]);
        i += 1;
    }

    let a_len: usize = a.len();

    let mut j: usize = 0;
    while j < b.len()
        invariant
            a_len == a@.len(),
            i == a_len,
            j <= b.len(),
            c@.len() == a_len as nat + j as nat,
            // the a-part is intact
            forall|k: int| 0 <= k < a@.len() ==> c@[k] == a@[k],
            // everything copied so far from b matches, shifted
            forall|t: int| 0 <= t < j as int ==> c@[a@.len() + t] == b@[t],
        decreases b.len() - j,
    {
        c.push(b[j]);
        j += 1;
    }

    // Help the verifier connect `a_len` with `a@.len()` in the postconditions.
    assert(a_len == a@.len());

    c
}

} // verus!

